// Which icon an affliction reads as, from the words the ability itself uses.
// The DoT specs carry a `label` ('Bleed', 'Burn', ...) and the ability its
// element, and those are what the artist drew icons for.
function statusKindForDot(spec) {
  const t = `${spec.label || ''} ${spec.kind || ''} ${spec.element || ''}`.toLowerCase();
  if (/bleed|hemor|laceration|gash/.test(t)) return 'bleeding';
  if (/poison|venom|toxin|blight|rot/.test(t)) return 'poisoned';
  if (/shock|lightning|volt|static|thunder/.test(t)) return 'shocked';
  return 'burning';   // fire, acid, and anything else that ticks
}
